// Core percentile math, ported from includes.R. The algorithms must
// replicate the R reference exactly; fixtures generated by
// scripts/generate_test_fixtures.R verify this.

export interface PercentileData {
  ages: number[];
  // Keys "1".."99", each an array parallel to ages.
  percentiles: Record<string, number[]>;
}

export interface DerivativeCurve {
  ages: number[];
  derivatives: number[];
}

export function round2(x: number): number {
  return Math.round(x * 100) / 100;
}

// The data's age column is pre-rounded to 2 decimals, so R's exact-match
// filter(age == round(age, 2)) is equivalent to nearest-row lookup here
// (float-safe; first minimum wins, like which.min).
export function nearestAgeIndex(ages: number[], age: number): number {
  const target = round2(age);
  let best = 0;
  let bestDiff = Infinity;
  for (let i = 0; i < ages.length; i++) {
    const diff = Math.abs(ages[i] - target);
    if (diff < bestDiff) {
      bestDiff = diff;
      best = i;
    }
  }
  return best;
}

// Port of calculate_percentile(): over the 99 percentile values at the
// patient's age row, return the percentile (1-99) whose value is closest
// to the measurement. First minimum wins, matching which.min.
export function calculatePercentile(
  data: PercentileData,
  age: number,
  measurement: number,
): number {
  const row = nearestAgeIndex(data.ages, age);
  let best = 1;
  let bestDiff = Infinity;
  for (let p = 1; p <= 99; p++) {
    const diff = Math.abs(data.percentiles[String(p)][row] - measurement);
    if (diff < bestDiff) {
      bestDiff = diff;
      best = p;
    }
  }
  return best;
}

export function isExtremePercentile(percentile: number): boolean {
  return percentile === 1 || percentile === 99;
}

// Centered rolling mean matching zoo::rollmean(x, k, fill = NA,
// align = "center") with the NA edges dropped. zoo pads
// floor((k-1)/2) NAs at the front (verified for k = 4, 5, 20), so the
// first window lands at output index `start` of the input grid. The
// cumulative-sum formulation mirrors zoo's implementation.
function rollmeanTrimmed(
  x: number[],
  k: number,
): { start: number; values: number[] } {
  const n = x.length;
  const cumsum = new Array<number>(n + 1);
  cumsum[0] = 0;
  for (let i = 0; i < n; i++) {
    cumsum[i + 1] = cumsum[i] + x[i];
  }
  const values: number[] = [];
  for (let i = 0; i + k <= n; i++) {
    values.push((cumsum[i + k] - cumsum[i]) / k);
  }
  return { start: Math.floor((k - 1) / 2), values };
}

// Port of calculate_percentile_derivative(). Note: callers pass the
// patient's percentile column (tab 1 behavior), not just 50.
// 1. Finite differences at midpoint ages
// 2. Centered rolling mean k=20, drop NA edges
// 3. Keep every 3rd point
// 4. Centered rolling mean k=5, drop NA edges
export function calculateDerivative(
  data: PercentileData,
  percentile: number,
): DerivativeCurve {
  const ages = data.ages;
  const values = data.percentiles[String(percentile)];
  const raw: number[] = [];
  const midAges: number[] = [];
  for (let i = 0; i < ages.length - 1; i++) {
    const ageDiff = ages[i + 1] - ages[i];
    raw.push((values[i + 1] - values[i]) / ageDiff);
    midAges.push(ages[i] + ageDiff / 2);
  }

  const smooth1 = rollmeanTrimmed(raw, 20);
  const ages1 = midAges.slice(
    smooth1.start,
    smooth1.start + smooth1.values.length,
  );

  const ages2: number[] = [];
  const values2: number[] = [];
  for (let i = 0; i < smooth1.values.length; i += 3) {
    ages2.push(ages1[i]);
    values2.push(smooth1.values[i]);
  }

  const smooth2 = rollmeanTrimmed(values2, 5);
  return {
    ages: ages2.slice(smooth2.start, smooth2.start + smooth2.values.length),
    derivatives: smooth2.values,
  };
}

// Port of interpolate_derivative_at_age(): linear interpolation
// (R's approx()), null outside the curve's age range.
export function interpolateDerivativeAtAge(
  curve: DerivativeCurve,
  targetAge: number,
): number | null {
  const { ages, derivatives } = curve;
  if (
    ages.length === 0 ||
    targetAge < ages[0] ||
    targetAge > ages[ages.length - 1]
  ) {
    return null;
  }
  for (let i = 0; i < ages.length - 1; i++) {
    if (targetAge >= ages[i] && targetAge <= ages[i + 1]) {
      const span = ages[i + 1] - ages[i];
      if (span === 0) {
        return derivatives[i];
      }
      const t = (targetAge - ages[i]) / span;
      return derivatives[i] + t * (derivatives[i + 1] - derivatives[i]);
    }
  }
  return derivatives[ages.length - 1];
}
